<?php require 'app.php';need_school();$sid=school_id();$sql='SELECT st.*,c.name class_name,c.stream FROM students st LEFT JOIN classes c ON c.id=st.class_id AND c.school_id=st.school_id WHERE st.school_id=?';$args=[$sid];if(in_array(role(),['patron','matron'],true)){$ids=assigned_class_ids();if(!$ids)$sql.=' AND 1=0';else{$sql.=' AND st.class_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$args=array_merge($args,$ids);}}$term=trim($_GET['q']??'');if($term!==''){$sql.=' AND (st.first_name ILIKE ? OR st.last_name ILIKE ? OR st.admission_number ILIKE ?)';array_push($args,"%$term%","%$term%","%$term%");}$sql.=' ORDER BY st.last_name,st.first_name LIMIT 500';$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();ob_start();?><div class="panel"><form method="get"><input name="q" placeholder="Search name or admission number" value="<?=h($term)?>"><button>Search</button></form><?php if(can_manage_students()):?><a class="btn" href="student_add.php">Register student</a><?php endif;?> <a class="btn" href="bulk_cards.php">Print cards</a><table><tr><th>Student</th><th>Admission No.</th><th>Class</th><th>Gender</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['first_name'].' '.$r['last_name'])?></td><td><?=h($r['admission_number'])?></td><td><?=h(($r['class_name']??'').' '.($r['stream']??''))?></td><td><?=h($r['gender'])?></td><td><a href="card.php?id=<?=$r['id']?>">View / print</a><?php if(can_manage_students()):?> · <a href="student_edit.php?id=<?=$r['id']?>">Edit</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php page('Students',ob_get_clean());
